"""Whisper audio decode without PyAV (Windows Smart App Control workaround)."""

from __future__ import annotations

import os
import subprocess
import sys
import tempfile
import types
from pathlib import Path
from typing import Any, BinaryIO, Union

from ..ffmpeg_util import resolve_ffmpeg


def _numpy():
    try:
        import numpy as np  # type: ignore
    except ImportError as err:
        raise RuntimeError(
            "缺少 numpy（Whisper 音频解码需要）。"
            "请重新下载 Whisper 模型以自动安装依赖，或执行："
            ' runtime\\python.exe -m pip install "numpy>=1.24.0" "faster-whisper>=1.1.0"'
            f" 原始错误: {err}"
        ) from err
    return np


def is_dll_policy_block(err: BaseException) -> bool:
    """True when Windows Application Control / SAC blocked a native module."""
    winerr = getattr(err, "winerror", None)
    if winerr == 4551:
        return True
    text = str(err) or ""
    if "4551" in text:
        return True
    if "DLL load failed" in text and (
        "应用程序控制" in text or "Application Control" in text or "blocked" in text.lower()
    ):
        return True
    # Nested cause (faster-whisper wraps ImportError)
    cause = getattr(err, "__cause__", None) or getattr(err, "__context__", None)
    if cause is not None and cause is not err:
        return is_dll_policy_block(cause)
    return False


def sac_policy_hint() -> str:
    return (
        "Windows「智能应用控制」仍在拦截引擎原生库（PyAV / 部分 torch DLL）。"
        "请到：Windows 安全中心 → 应用和浏览器控制 → 智能应用控制 → 关闭，"
        "再将引擎安装目录下的 .venv 加入 Defender 排除项，并完全重启 Transub。"
    )


def pad_or_trim(array: Any, length: int = 3000, *, axis: int = -1) -> Any:
    """Same contract as faster_whisper.audio.pad_or_trim."""
    np = _numpy()
    if array.shape[axis] > length:
        array = array.take(indices=range(length), axis=axis)
    if array.shape[axis] < length:
        pad_widths = [(0, 0)] * array.ndim
        pad_widths[axis] = (0, length - array.shape[axis])
        array = np.pad(array, pad_widths)
    return array


def decode_audio_ffmpeg(
    input_file: Union[str, BinaryIO],
    sampling_rate: int = 16000,
    split_stereo: bool = False,
) -> Any:
    """
    Decode audio via bundled/system ffmpeg → s16le PCM → float32.
    Used when PyAV cannot load (Smart App Control blocking av*.pyd).
    """
    np = _numpy()
    ffmpeg = resolve_ffmpeg()
    if not ffmpeg:
        raise RuntimeError(
            "PyAV 不可用且未找到 ffmpeg。请在设置 → 环境 → FFmpeg 中配置路径。"
            f" {sac_policy_hint()}"
        )

    tmp_path: str | None = None
    try:
        if hasattr(input_file, "read"):
            suffix = ".bin"
            name = getattr(input_file, "name", "") or ""
            if isinstance(name, str) and Path(name).suffix:
                suffix = Path(name).suffix
            fd, tmp_path = tempfile.mkstemp(prefix="transub_av_", suffix=suffix)
            os.close(fd)
            with open(tmp_path, "wb") as out:
                while True:
                    chunk = input_file.read(1024 * 1024)
                    if not chunk:
                        break
                    out.write(chunk)
            src = tmp_path
        else:
            src = str(input_file)

        channels = 2 if split_stereo else 1
        cmd = [
            ffmpeg,
            "-nostdin",
            "-hide_banner",
            "-loglevel",
            "error",
            "-i",
            src,
            "-f",
            "s16le",
            "-acodec",
            "pcm_s16le",
            "-ac",
            str(channels),
            "-ar",
            str(int(sampling_rate)),
            "pipe:1",
        ]
        run_kwargs: dict[str, Any] = {
            "capture_output": True,
            "check": False,
        }
        if os.name == "nt":
            run_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        proc = subprocess.run(cmd, **run_kwargs)
        if proc.returncode != 0 or not proc.stdout:
            err = (proc.stderr or b"").decode("utf-8", errors="replace").strip()
            raise RuntimeError(f"ffmpeg decode failed ({proc.returncode}): {err[:500]}")

        audio = np.frombuffer(proc.stdout, dtype=np.int16).astype(np.float32) / 32768.0
        if split_stereo:
            return audio[0::2], audio[1::2]
        return audio
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


def install_faster_whisper_ffmpeg_audio_shim() -> None:
    """
    Pre-register faster_whisper.audio so package import skips broken PyAV.
    Call only after clearing failed partial imports.
    """
    shim = types.ModuleType("faster_whisper.audio")
    shim.decode_audio = decode_audio_ffmpeg
    shim.pad_or_trim = pad_or_trim
    shim.__file__ = "<transub_engine.asr.whisper_av_shim>"
    sys.modules["faster_whisper.audio"] = shim


def clear_faster_whisper_modules() -> None:
    for key in list(sys.modules):
        if key == "av" or key.startswith("av.") or key.startswith("faster_whisper"):
            del sys.modules[key]


def _install_long_media_patches() -> None:
    """Bound peak RAM on multi-hour files (full-file complex128 STFT)."""
    try:
        from .whisper_feature_patch import install_chunked_mel_patch

        install_chunked_mel_patch()
    except Exception:
        pass


def import_whisper_model_class() -> tuple[Any, bool]:
    """
    Returns (WhisperModel class, used_ffmpeg_shim).
    Falls back to ffmpeg decode when PyAV is blocked by Application Control.
    """
    try:
        from faster_whisper import WhisperModel  # type: ignore

        _install_long_media_patches()
        return WhisperModel, False
    except Exception as err:
        if not is_dll_policy_block(err) and "DLL load failed" not in str(err):
            raise RuntimeError(
                "Whisper 需要 faster-whisper。"
                "请执行: pip install 'transub-engine[asr-whisper]'"
                f" 原始错误: {err}"
            ) from err

    clear_faster_whisper_modules()
    install_faster_whisper_ffmpeg_audio_shim()
    try:
        from faster_whisper.transcribe import WhisperModel  # type: ignore

        _install_long_media_patches()
        return WhisperModel, True
    except Exception as err:
        raise RuntimeError(
            "Whisper / PyAV 无法加载，且 ffmpeg 回退失败。"
            f" {sac_policy_hint()} 原始错误: {err}"
        ) from err
